param([Parameter(Mandatory=$true)][string]$RunPath,[string]$Stage1ReportPath='')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$records=@();$cases=@(@{Suite='basic'},@{Suite='budgets'},@{Suite='cost'},@{Suite='roots'},@{Suite='project'},@{Suite='project';BrokenProject=$true},@{Suite='project';ProjectCount=8},@{Suite='project';ProjectCount=32},@{Suite='project';ProjectCount=128},@{FaultDomain=1},@{FaultDomain=2},@{FaultDomain=1;OneShot=$true},@{FaultDomain=2;OneShot=$true},@{Control='small'},@{Suite='cost';Control='cost-value'},@{Suite='cost';Control='cost-metric'},@{Suite='project';BrokenProject=$true;Control='order'})
foreach($case in $cases){$arguments=@{RunPath=$RunPath;Stage1ReportPath=$Stage1ReportPath};foreach($key in $case.Keys){$arguments[$key]=$case[$key]};$output=@(& (Join-Path $PSScriptRoot 'resource-check.ps1') @arguments);$path=($output|Where-Object {$_ -like 'Evidence: *'}|Select-Object -Last 1).Substring(10);$report=[IO.File]::ReadAllText($path)|ConvertFrom-Json;if(-not $report.success){throw "Failed child $path"};$records+=@([pscustomobject]@{parameters=$arguments;report=[IO.Path]::GetFullPath($path);native=$report.native});Write-Output "Completed $($records.Count)/$($cases.Count): $path"}
$path=Join-Path $RunPath ('resource-cohort-'+[Guid]::NewGuid().ToString('N')+'.json');[pscustomobject]@{success=$true;diagnosticOnly=$true;stage1Report=$Stage1ReportPath;cases=$records}|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $path -Encoding UTF8;Write-Output "Cohort: $path"
